<?php declare(strict_types=1);require __DIR__.'/../../includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('admin/login.php');verify_csrf($_POST['csrf_token']??null);$email=strtolower(trim((string)$_POST['email']));$pass=(string)$_POST['password'];$s=db()->prepare('SELECT user_id,role,name,email,password_hash,status FROM users WHERE email=? AND role="admin" LIMIT 1');$s->execute([$email]);$u=$s->fetch();if(!$u||$u['status']!=='active'||!password_verify($pass,$u['password_hash'])){flash('admin_error','Invalid administrator credentials.');redirect('admin/login.php');}login_user($u);add_activity((int)$u['user_id'],'login','admin',(int)$u['user_id']);redirect('admin/dashboard.php');